using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed record RecordedRequest(string Method, string Path, string? ContentType, string Body);

/// <summary>Real local HTTP server standing in for the provider; records what it receives.</summary>
public sealed class ProviderStub : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int status;
    private readonly string body;
    private readonly Task loop;

    public ProviderStub(int status, string body)
    {
        this.status = status;
        this.body = body;
        var port = GetFreePort();
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
        listener.Start();
        loop = Task.Run(Serve);
    }

    public Uri BaseAddress { get; }

    public List<RecordedRequest> Requests { get; } = [];

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            var requestBody = await reader.ReadToEndAsync();
            lock (Requests)
                Requests.Add(new(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath, ctx.Request.ContentType, requestBody));

            var bytes = Encoding.UTF8.GetBytes(body);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private static int GetFreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(2));
    }
}
