using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, ProviderStub Stub)> Authorize(int status, string body)
    {
        using var stub = new ProviderStub(status, body);
        using var client = new HttpClient { BaseAddress = stub.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        return (outcome, stub);
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_as_json_with_reference_amount_and_currency()
    {
        var (_, stub) = await Authorize(200, """{"status":"approved"}""");

        var request = Assert.Single(stub.Requests);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, _) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        var (outcome, _) = await Authorize(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_payment_refused_outright_with_402_is_declined()
    {
        var (outcome, _) = await Authorize(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Any_other_failure_status_is_surfaced_not_mistaken_for_a_decision(int status)
    {
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_surfaced_as_an_error()
    {
        await Assert.ThrowsAsync<JsonException>(() => Authorize(200, "<html>oops</html>"));
    }
}
